 static_assert(swam.lochte() == 12); // error: invoking virtual function on reference
 // with constexpr-unknown dynamic type
 static_assert(swam.coughlin == 12); // error: lvalue-to-rvalue conversion on an object
 // not usable in constant expressions
}
extern Swim dc;
extern Swim& trident;
constexpr auto& sandeno = typeid(dc); // OK, can only be typeid(Swim)
constexpr auto& gallagher = typeid(trident); // error: constexpr-unknown dynamic type

— end example]

If an expression of literal class type is used in a context where an integral constant expression is required, then that expression is contextually implicitly converted ([conv]) to an integral or unscoped enumeration type and the selected conversion function shall be constexpr. [Example 6:

struct A {
 constexpr A(int i) : val(i) { }
 constexpr operator int() const { return val; }
 constexpr operator long() const { return 42; }
private:
