}

— end example]

An expression or conversion is manifestly constant-evaluated if it is: a constant-expression, orthe condition of a constexpr if statement ([stmt.if]), oran immediate invocation, orthe result of substitution into an atomic constraint expression to determine whether it is satisfied ([temp.constr.atomic]), orthe initializer of a variable that is usable in constant expressions or has constant initialization ([basic.start.static]). [Example 10:

template<bool> struct X {};
X<std::is_constant_evaluated()> x; // type X<true>
int y;
const int a = std::is_constant_evaluated() ? y : 1; // dynamic initialization to 1
double z[a]; // error: a is not usable
 // in constant expressions
const int b = std::is_constant_evaluated() ? 2 : y; // static initialization to 2
int c = y + (std::is_constant_evaluated() ? 2 : y); // dynamic initialization to y+y
constexpr int f() {
 const int n = std::is_constant_evaluated() ? 13 : 17; // n is 13
 int m = std::is_constant_evaluated() ? 13 : 17; // m can be 13 or 17 (see below)
 char arr[n] = {}; // char[13]
 return m + sizeof(arr);
}
int p = f(); // m is 13; initialized to 26
int q = p + f(); // m is 17 for this call; initialized to 56

— end example] [Note 10: A manifestly constant-evaluated expression is evaluated even in an unevaluated operand. — end note]
